#include "rensga/audio/ps2_audio.h"

#include <audsrv.h>
#include <iopheap.h>
#include <loadfile.h>
#include <sbv_patches.h>
#include <sifrpc.h>
#include <string.h>

#include "rensga/core/log.h"

// Generated by bin2c from $PS2SDK/iop/irx/audsrv.irx (see CMakeLists.txt).
extern "C" unsigned char audsrv_irx[];
extern "C" unsigned int size_audsrv_irx;

namespace rensga {

bool Ps2Audio::init(u32 sampleRate, AudioMixer* mixer) {
  if (!mixer || sampleRate == 0) return true;
  SifInitRpc(0);
  int id = SifLoadModule("rom0:LIBSD", 0, nullptr);
  if (id < 0) {
    RLOG_ERROR("audio", "rom0:LIBSD failed (%d)", id);
    return false;
  }
  // The BIOS LOADFILE of older consoles cannot load a module from an EE buffer: patch it (libpatches) first.
  SifInitIopHeap();
  SifLoadFileInit();
  const int lmb = sbv_patch_enable_lmb();
  if (lmb != 0) RLOG_WARN("audio", "sbv_patch_enable_lmb returned %d", lmb);
  int ret = 0;
  id = SifExecModuleBuffer(audsrv_irx, size_audsrv_irx, 0, nullptr, &ret);
  if (id < 0 || ret == 1) {  // ret 1 = the module asked to be unloaded (init failed)
    RLOG_ERROR("audio", "audsrv.irx failed (%d, %d)", id, ret);
    return false;
  }
  if (audsrv_init() != 0) {
    RLOG_ERROR("audio", "audsrv_init failed: %s", audsrv_get_error_string());
    return false;
  }
  audsrv_fmt_t fmt;
  fmt.freq = static_cast<int>(sampleRate);
  fmt.bits = 16;
  fmt.channels = 2;
  if (audsrv_set_format(&fmt) != AUDSRV_ERR_NOERROR) {
    RLOG_ERROR("audio", "audsrv_set_format failed: %s", audsrv_get_error_string());
    return false;
  }
  audsrv_set_volume(MAX_VOLUME);
  mixer_ = mixer;
  rate_ = sampleRate;
  return true;
}

void Ps2Audio::shutdown() {
  if (mixer_) audsrv_quit();
  mixer_ = nullptr;
  rate_ = 0;
}

// Fills whatever room the IOP ring has, in chunks. All on the main thread, so the mixer needs no lock.
void Ps2Audio::update() {
  if (!mixer_) return;
  mixer_->update();
  alignas(16) static i16 chunk[1024 * 2];
  for (int guard = 0; guard < 4; ++guard) {
    int room = audsrv_available();  // bytes
    if (room < static_cast<int>(sizeof(chunk) / 2)) break;
    u32 frames = static_cast<u32>(room) / 4;
    if (frames > 1024) frames = 1024;
    mixer_->mix(chunk, frames);
    audsrv_play_audio(reinterpret_cast<const char*>(chunk), static_cast<int>(frames * 4));
  }
}

}  // namespace rensga
